    {
      "rank": 1,
      "ballot_id": "B026",
      "proposed_laureates": [
        "Christopher Jarzynski",
        "Gavin E. Crooks",
        "Denis J. Evans"
      ],
      "assessment": {
        "nobel_worthiness": "Fluctuation relations made nonequilibrium statistical mechanics quantitative, connecting microscopic dynamics to macroscopic irreversibility with broad consequences for experiments and theory.",
        "attribution": "Jarzynski and Crooks established central work relations, while Evans and collaborators developed foundational fluctuation theorems. Credit is substantial across a connected body of work, though the contributions are not identical.",
        "maturity": "The relations have been tested and applied over decades in small systems, including biomolecular and colloidal experiments; the conceptual contribution is well established.",
        "uncertainties": [
          "The long, distributed history of fluctuation relations makes a three-person attribution difficult.",
          "The committee may judge the advance too specialized relative to the broadest Nobel-recognized principles."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Peter W. Shor",
        "Andrew M. Steane",
        "Alexei Kitaev"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction identified how fragile quantum information can be protected in principle, turning scalable quantum computation from a formal impossibility into a physical program.",
        "attribution": "Shor and Steane independently introduced landmark codes; Kitaev's topological codes connected error correction to deep ideas in condensed matter and fault tolerance. These are distinct, highly consequential contributions.",
        "maturity": "The principles are rigorously established and now underpin experimental quantum processors, although large-scale fault-tolerant operation remains incomplete.",
        "uncertainties": [
          "The prize timing may depend on whether the committee requires demonstrated large-scale fault tolerance.",
          "The field has many important later contributors beyond the three named here."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B004",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Markus Greiner",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Optical-lattice experiments created a remarkably clean and controllable setting for studying strongly correlated quantum matter, including canonical lattice models that are difficult to access elsewhere.",
        "attribution": "Bloch and Greiner led pioneering experiments, while Zoller helped establish the theoretical framework and vision for quantum simulation with cold atoms. Cirac's contribution is also significant, so a three-person limit requires a difficult boundary.",
        "maturity": "The platform is experimentally mature, reproducible, and productive across many-body physics; its value as a simulator is established even as more ambitious simulation goals continue.",
        "uncertainties": [
          "Credit among the leading experimental and theoretical groups is broad.",
          "The distinction between a new simulator and discoveries made using it may affect the prize case."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B013",
      "proposed_laureates": [
        "Antoine Georges",
        "Dieter Vollhardt",
        "Gabriel Kotliar"
      ],
      "assessment": {
        "nobel_worthiness": "Dynamical mean-field theory provided a powerful, general framework for treating local electronic correlations and became central to modern understanding of strongly correlated materials.",
        "attribution": "Georges, Kotliar, and Vollhardt were central to formulating and developing the method. Its conceptual lineage and collaborative development make precise individual credit challenging.",
        "maturity": "The theory has been extensively tested against experiment and extended computationally for decades; it is a mature tool with continuing scientific reach.",
        "uncertainties": [
          "The method's success is broad but incremental extensions and community development complicate a sharply bounded discovery claim.",
          "The Nobel may favor a specific physical phenomenon over a widely used theoretical framework."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B031",
      "proposed_laureates": [
        "Charles L. Kane",
        "Eugene J. Mele",
        "Laurens W. Molenkamp",
        "M. Zahid Hasan"
      ],
      "assessment": {
        "nobel_worthiness": "The quantum spin Hall effect and topological insulators revealed a new organizing principle for electronic phases, with robust boundary states protected by topology and symmetry.",
        "attribution": "Kane and Mele established the theoretical framework, while Molenkamp and Hasan led influential experimental demonstrations. The four credited names span complementary foundational contributions.",
        "maturity": "The basic phases and their characteristic transport and spectroscopic signatures are well established, though materials limitations and disorder shape applications.",
        "uncertainties": [
          "The broader topological-matter field has many essential contributors, making the boundary of this particular prize difficult.",
          "The closely overlapping topological-insulator ballot creates ambiguity about the intended scope."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B021",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks transformed precision timekeeping by sharply reducing atomic motion and systematic shifts, opening tests of fundamental physics and new measurement capabilities.",
        "attribution": "Katori and Ye independently developed leading approaches that established the field; their contributions are complementary and the two-person attribution is persuasive.",
        "maturity": "The clocks have achieved extraordinary precision and reproducibility in multiple laboratories, though the full redefinition of the second remains ahead.",
        "uncertainties": [
          "The committee may wait for international adoption or a formal change in the definition of the second.",
          "Related precision-clock advances involve a wider community."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B016",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit quantum electrodynamics made coherent interactions between artificial atoms and microwave photons experimentally accessible, becoming a foundation of superconducting quantum information processing.",
        "attribution": "Blais developed the central theoretical architecture, with Wallraff and Schoelkopf among the experimental pioneers who demonstrated and established it. Credit is strong but the field expanded rapidly through many groups.",
        "maturity": "The basic effects are replicated and the platform is now used in increasingly capable quantum processors; practical scale and error correction remain active challenges.",
        "uncertainties": [
          "The Nobel case may depend on whether the prize recognizes a foundational platform or waits for a clear computational milestone.",
          "The boundary between circuit QED and broader superconducting-circuit work is not sharp."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B017",
      "proposed_laureates": [
        "Juan Maldacena",
        "Edward Witten"
      ],
      "assessment": {
        "nobel_worthiness": "Gauge/gravity duality is a striking theoretical connection that has influenced quantum field theory, gravity, and strongly coupled many-body physics.",
        "attribution": "Maldacena's conjecture was the decisive formulation; Witten provided influential development and interpretation. Polyakov's earlier work is important to the intellectual background, complicating a clean attribution.",
        "maturity": "The duality is mathematically powerful and supported by extensive internal consistency, but its most direct physical setting remains theoretical rather than experimentally confirmed.",
        "uncertainties": [
          "The absence of direct empirical tests of the proposed gravitational dual limits the Nobel case.",
          "The result's scope and attribution depend on distinguishing the original conjecture from its wider development."
        ]
      }
    }
  ]
